import sys

def max_operations(N, a):
    max_ops = 0
    for num in a:
        ops = 0
        while num % 2 == 0:
            num //= 2
            ops += 1
        while num % 3 == 0:
            num //= 3
            ops += 1
        if num == 1:
            max_ops = max(max_ops, ops)
    return max_ops

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    a = list(map(int, data[1:]))
    print(max_operations(N, a))
